struct Particle {
    glm::vec3 position;
    float pressure;
};

glm::vec3 calculatePressureForce(Particle* pi, Particle* pj, float mass, float spikyGrad, float h) {
    glm::vec3 rij = pi->position - pj->position;
    float r = glm::length(rij);
    if (r == 0.0f) {
        return glm::vec3(0.0f);
    }
    float avgPressure = (pi->pressure + pj->pressure) * 0.5f;
    glm::vec3 kernelGrad = spikyGrad * std::pow(h - r, 2) * (rij / r);
    return -mass * avgPressure * kernelGrad;
}

